		connection = repository.getConnection();
		ValueFactory vf = connection.getValueFactory();
		IRI p = vf.createIRI(EX, "p");
		IRI q = vf.createIRI(EX, "q");
		connection.begin();
		for (int key = 0; key < keyCount; key++) {
			for (int value = 0; value < fanOut; value++) {
				IRI subject = vf.createIRI(EX, "key/" + key);
				IRI object = vf.createIRI(EX, "value/" + value);
				connection.add(subject, p, object);
				connection.add(subject, q, object);
			}
		}
		connection.commit();
		if (store.rebuildFrontierStatistics().availability() != FrontierStatisticsAvailability.READY) {
			throw new IllegalStateException("Support-join fixture requires current Frontier statistics");
		}

		StringBuilder values = new StringBuilder();
		Map<BindingSet, Integer> expected = new HashMap<>();
		for (int outer = 0; outer < OUTER_ROWS; outer++) {
			values.append("(<")
					.append(EX)
					.append("outer/")
					.append(outer)
					.append("> <")
					.append(EX)
					.append("key/")
					.append(outer % keyCount)
					.append(">) ");
			for (int value = 0; value < fanOut; value++) {
				expected.put(new ListBindingSet(OUTPUT_NAMES, vf.createIRI(EX, "outer/" + outer),
						vf.createIRI(EX, "value/" + value)), 2);
			}
		}
		String body = "WHERE { VALUES (?outer ?key) { " + values
				+ "} OPTIONAL { { ?key <" + EX + "p> ?value } UNION { ?key <" + EX + "q> ?value } } }";
		rowsQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, "SELECT ?outer ?value " + body);
		query = connection.prepareTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?outer ?value (COUNT(*) AS ?copies) " + body + " GROUP BY ?outer ?value");
